#include "transfer.h"
#include <stdlib.h>
/* One input is a complete session. No reset between commands unless opcode0. */
int LLVMFuzzerTestOneInput(const unsigned char*p,size_t n){VTStream s={0};unsigned char raw[18];size_t used=0;int bad=0;vt_reset(&s);size_t at=0;while(at<n){unsigned op=p[at++]%3;if(op==0){vt_reset(&s);used=0;bad=0;}else if(op==1){if(at==n)break;size_t len=p[at++]%20;if(len>n-at)len=n-at;for(size_t i=0;i<len;i++){if(used>=18||(used&&used>=(size_t)raw[0]+2)||(!used&&p[at+i]>16))bad=1;if(!bad)raw[used++]=p[at+i];}int accepted=vt_feed(&s,p+at,len);if(accepted==bad)abort();at+=len;}else{uint32_t out=91,want=0;unsigned x=0;int good=!bad&&used>=2&&used==(size_t)raw[0]+2;if(good){for(size_t i=1;i+1<used;i++){x^=raw[i];want=want*33+raw[i];}good=x==raw[used-1];}int ok=vt_finish(&s,&out);if(ok!=good||(ok?out!=want:out!=91))abort();}}return 0;}
